import nodemailer from "nodemailer";
//#region src/lib/school/notify-send.server.ts
function normalizePh(raw) {
	const digits = raw.replace(/\D/g, "");
	if (digits.length === 11 && digits.startsWith("09")) return `63${digits.slice(1)}`;
	if (digits.length === 12 && digits.startsWith("63")) return digits;
	if (digits.length === 10 && digits.startsWith("9")) return `63${digits}`;
	return "";
}
function clip(msg) {
	return msg.replace(/pass(word)?=[^&\s]+/gi, "pass=***").slice(0, 180);
}
async function sendEmail(input) {
	const host = input.host.trim() || "smtp.gmail.com";
	const gmail = host.includes("gmail");
	const transporter = nodemailer.createTransport({
		host,
		port: gmail ? 465 : 587,
		secure: gmail,
		auth: {
			user: input.user.trim(),
			pass: input.pass
		},
		connectionTimeout: 8e3,
		socketTimeout: 8e3
	});
	try {
		await transporter.sendMail({
			from: `"${input.fromName}" <${input.user.trim()}>`,
			to: input.to.trim(),
			subject: input.subject.slice(0, 120),
			text: input.text.slice(0, 500)
		});
		return {
			ok: true,
			detail: `Sent to ${input.to.trim()}`
		};
	} catch (error) {
		return {
			ok: false,
			detail: clip(error instanceof Error ? error.message : "Email could not be sent.")
		};
	} finally {
		transporter.close();
	}
}
async function sendSms(input) {
	const number = normalizePh(input.number);
	if (!number) return {
		ok: false,
		detail: "Mobile number is not a valid PH number."
	};
	try {
		const body = new URLSearchParams({
			apikey: input.apiKey.trim(),
			number,
			message: input.message.slice(0, 300)
		});
		if (input.sender.trim()) body.set("sendername", input.sender.trim().slice(0, 11));
		const res = await fetch("https://api.semaphore.co/api/v4/messages", {
			method: "POST",
			headers: { "Content-Type": "application/x-www-form-urlencoded" },
			body,
			signal: AbortSignal.timeout(8e3)
		});
		const text = await res.text();
		if (!res.ok) return {
			ok: false,
			detail: clip(text || `SMS HTTP ${res.status}`)
		};
		return {
			ok: true,
			detail: `Sent to ${number}`
		};
	} catch (error) {
		return {
			ok: false,
			detail: clip(error instanceof Error ? error.message : "SMS could not be sent.")
		};
	}
}
//#endregion
export { sendEmail, sendSms };
